// Build current vs prior week metrics for all four sections.
// The digest runs Monday morning, so the "current" reporting window is the
// most recently COMPLETED Monday–Sunday week, and "prior" is the week before it.
const threshold = 20; // anomaly cutoff in % (n8n blocks $env inside Code nodes)

const now = new Date();
const day = now.getDay(); // 0 = Sunday .. 6 = Saturday
const mondayThisWeek = new Date(now);
mondayThisWeek.setHours(0, 0, 0, 0);
mondayThisWeek.setDate(mondayThisWeek.getDate() - (day === 0 ? 6 : day - 1));

const curStart = new Date(mondayThisWeek);
curStart.setDate(curStart.getDate() - 7);
const curEnd = new Date(mondayThisWeek); // exclusive
const priorStart = new Date(curStart);
priorStart.setDate(priorStart.getDate() - 7);
const priorEnd = new Date(curStart); // exclusive

const inRange = (v, start, end) => {
  const t = new Date(v);
  return !isNaN(t) && t >= start && t < end;
};
const num = (v) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};
const round1 = (n) => Math.round(n * 10) / 10;
const round2 = (n) => Math.round(n * 100) / 100;
const pctChange = (cur, prior) =>
  prior === 0 ? (cur === 0 ? 0 : 100) : round1(((cur - prior) / prior) * 100);
const money = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const rowsOf = (nodeName) => $(nodeName).all().map((i) => i.json);
const splitWeeks = (rows) => ({
  current: rows.filter((r) => inRange(r.Date, curStart, curEnd)),
  prior: rows.filter((r) => inRange(r.Date, priorStart, priorEnd)),
});
const sampleText = (rows, cols) =>
  rows.slice(0, 5).map((r) => cols.map((c) => c + '=' + (r[c] ?? '')).join(', ')).join(' | ') ||
  'no rows recorded this week';

// --- Leads: total leads = number of rows
const leads = splitWeeks(rowsOf('Get Leads Data'));
const leadsCur = leads.current.length;
const leadsPrior = leads.prior.length;
const leadsChange = pctChange(leadsCur, leadsPrior);

// --- Revenue: sum of the Amount column
const revenue = splitWeeks(rowsOf('Get Revenue Data'));
const revCur = round2(revenue.current.reduce((s, r) => s + num(r.Amount), 0));
const revPrior = round2(revenue.prior.reduce((s, r) => s + num(r.Amount), 0));
const revChange = pctChange(revCur, revPrior);

// --- Support: total tickets = sum of Tickets; also resolved + average first-response time
const support = splitWeeks(rowsOf('Get Support Data'));
const ticketsCur = support.current.reduce((s, r) => s + num(r.Tickets), 0);
const ticketsPrior = support.prior.reduce((s, r) => s + num(r.Tickets), 0);
const ticketsChange = pctChange(ticketsCur, ticketsPrior);
const resolvedCur = support.current.reduce((s, r) => s + num(r.Resolved), 0);
const avgResp = (rows) =>
  rows.length ? round1(rows.reduce((s, r) => s + num(r.Avg_Response_hrs), 0) / rows.length) : 0;
const respCur = avgResp(support.current);
const respPrior = avgResp(support.prior);

// --- Ad Spend: sum Spend, sum Conversions, CPA = Spend / Conversions
const ads = splitWeeks(rowsOf('Get Ad Spend Data'));
const spendCur = round2(ads.current.reduce((s, r) => s + num(r.Spend), 0));
const spendPrior = round2(ads.prior.reduce((s, r) => s + num(r.Spend), 0));
const spendChange = pctChange(spendCur, spendPrior);
const convCur = ads.current.reduce((s, r) => s + num(r.Conversions), 0);
const convPrior = ads.prior.reduce((s, r) => s + num(r.Conversions), 0);
const convChange = pctChange(convCur, convPrior);
const cpaCur = convCur ? round2(spendCur / convCur) : 0;
const cpaPrior = convPrior ? round2(spendPrior / convPrior) : 0;

const fmtNice = (d) => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
const lastDay = new Date(curEnd.getTime() - 86400000);
const weekRange = fmtNice(curStart) + ' – ' + fmtNice(lastDay) + ', ' + curStart.getFullYear();

const section = (name, metric, prior, change, formatted, extra) => ({
  name,
  metric,
  prior,
  change,
  direction: change >= 0 ? 'up' : 'down',
  anomaly: Math.abs(change) > threshold,
  formatted,
  ...extra,
});

return [
  {
    json: {
      weekRange,
      generatedDate: now.toISOString().slice(0, 10),
      threshold,
      leads: section('Leads', leadsCur, leadsPrior, leadsChange, leadsCur + ' leads', {
        sampleText: sampleText(leads.current, ['Date', 'Source', 'Grade', 'Converted']),
      }),
      revenue: section('Revenue', revCur, revPrior, revChange, '$' + money(revCur), {
        sampleText: sampleText(revenue.current, ['Date', 'Amount', 'Product', 'Channel']),
      }),
      support: section('Support', ticketsCur, ticketsPrior, ticketsChange, ticketsCur + ' tickets', {
        resolved: resolvedCur,
        avgResponseHrs: respCur,
        avgResponseHrsPrior: respPrior,
        subline: resolvedCur + ' resolved · avg first response ' + respCur + ' hrs (was ' + respPrior + ' hrs)',
        sampleText: sampleText(support.current, ['Date', 'Tickets', 'Resolved', 'Avg_Response_hrs']),
      }),
      adSpend: section('Ad Spend', spendCur, spendPrior, spendChange, '$' + money(spendCur), {
        conversions: convCur,
        conversionsPrior: convPrior,
        conversionsChange: convChange,
        cpa: cpaCur,
        cpaPrior: cpaPrior,
        subline: convCur + ' conversions · CPA $' + money(cpaCur) + ' (was $' + money(cpaPrior) + ')',
        sampleText: sampleText(ads.current, ['Date', 'Platform', 'Spend', 'Clicks', 'Conversions']),
      }),
    },
  },
];

