// Assemble the HTML email and the condensed Slack message from the metrics
// and the LLM-generated summaries / focus block.
const m = $('Calculate Metrics').first().json;
const summaries = {
  leads: ($('Summarize Leads').first().json.text || '').trim(),
  revenue: ($('Summarize Revenue').first().json.text || '').trim(),
  support: ($('Summarize Support').first().json.text || '').trim(),
  adSpend: ($('Summarize Ad Spend').first().json.text || '').trim(),
};

const focusRaw = $('Generate Focus Block').first().json.text || '';
const focusBullets = focusRaw
  .split('\n')
  .map((l) => l.replace(/^\s*(?:[-•*]|\d+[.)])\s*/, '').trim())
  .filter((l) => l.length > 0);

const sign = (n) => (n >= 0 ? '+' : '');
const badgeClass = (n) => (Math.abs(n) <= 5 ? 'badge-neutral' : n > 0 ? 'badge-up' : 'badge-down');
const emoji = (n) => (Math.abs(n) <= 5 ? '➡️' : n > 0 ? '✅' : '🔴');
const oneLine = (txt) => (txt || '').replace(/\s+/g, ' ').trim();

const sections = [m.leads, m.revenue, m.support, m.adSpend];
const summaryFor = (s) =>
  s.name === 'Leads' ? summaries.leads :
  s.name === 'Revenue' ? summaries.revenue :
  s.name === 'Support' ? summaries.support : summaries.adSpend;

const sectionHtml = sections
  .map((s) => {
    const summary = summaryFor(s);
    const anomalyBox = s.anomaly
      ? `<div class="anomaly-box">⚠️ Anomaly — ${s.name} ${s.direction === 'up' ? 'rose' : 'fell'} ${Math.abs(s.change)}% versus last week, outside the normal ±${m.threshold}% range. Worth a closer look.</div>`
      : '';
    const subline = s.subline ? `<div class="subline">${s.subline}</div>` : '';
    return `  <div class="section">
    <div class="section-title">${s.name}</div>
    <div class="metric-row">
      <span class="metric-value">${s.formatted}</span>
      <span class="${badgeClass(s.change)}">${sign(s.change)}${s.change}% vs last week</span>
    </div>
    ${subline}
    ${anomalyBox}
    <p class="summary-text">${summary}</p>
  </div>`;
  })
  .join('\n');

const focusHtml = (focusBullets.length ? focusBullets : ['No anomalies this week — keep doing what is working.'])
  .map((b) => `      <li>${b}</li>`)
  .join('\n');

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; color: #1a1a1a; }
    .header { background: #1a1a1a; color: white; padding: 24px; border-radius: 8px 8px 0 0; }
    .header h1 { margin: 0; font-size: 20px; }
    .header p { margin: 4px 0 0; font-size: 13px; color: #999; }
    .section { padding: 20px 24px; border-bottom: 1px solid #eee; }
    .section-title { font-size: 14px; font-weight: bold; color: #555; text-transform: uppercase; letter-spacing: 0.5px; }
    .metric-row { display: flex; align-items: baseline; gap: 12px; margin: 8px 0; }
    .metric-value { font-size: 28px; font-weight: bold; }
    .subline { font-size: 13px; color: #888; margin: 0 0 6px; }
    .badge-up { background: #d1fae5; color: #065f46; padding: 2px 8px; border-radius: 12px; font-size: 12px; }
    .badge-down { background: #fee2e2; color: #991b1b; padding: 2px 8px; border-radius: 12px; font-size: 12px; }
    .badge-neutral { background: #f3f4f6; color: #374151; padding: 2px 8px; border-radius: 12px; font-size: 12px; }
    .anomaly-box { background: #fffbeb; border-left: 3px solid #f59e0b; padding: 10px 14px; margin: 10px 0; border-radius: 0 6px 6px 0; font-size: 13px; color: #92400e; }
    .summary-text { font-size: 14px; color: #444; line-height: 1.6; margin: 8px 0 0; }
    .focus-section { padding: 20px 24px; background: #f9fafb; }
    .focus-section h2 { font-size: 15px; margin: 0 0 12px; }
    .focus-section ul { margin: 0; padding-left: 18px; }
    .focus-section li { font-size: 14px; color: #444; margin-bottom: 6px; line-height: 1.5; }
    .footer { padding: 16px 24px; font-size: 12px; color: #999; text-align: center; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Weekly Business Digest</h1>
    <p>${m.weekRange} · Generated by AI Weekly Digest</p>
  </div>
${sectionHtml}
  <div class="focus-section">
    <h2>🎯 Focus for this week</h2>
    <ul>
${focusHtml}
    </ul>
  </div>
  <div class="footer">AI Weekly Digest · ${m.generatedDate}</div>
</body>
</html>`;

const subject = `Weekly Business Digest — ${m.weekRange}`;

const slackText = [
  `📊 *Weekly Business Digest — ${m.weekRange}*`,
  '',
  `📋 *Leads:* ${m.leads.metric} ${emoji(m.leads.change)} ${sign(m.leads.change)}${m.leads.change}%`,
  oneLine(summaries.leads),
  '',
  `💰 *Revenue:* ${m.revenue.formatted} ${emoji(m.revenue.change)} ${sign(m.revenue.change)}${m.revenue.change}%`,
  oneLine(summaries.revenue),
  '',
  `🎧 *Support:* ${m.support.metric} tickets ${emoji(m.support.change)} ${sign(m.support.change)}${m.support.change}%`,
  oneLine(summaries.support),
  '',
  `📣 *Ad Spend:* ${m.adSpend.formatted} → ${m.adSpend.conversions} conversions ${emoji(m.adSpend.change)} ${sign(m.adSpend.change)}${m.adSpend.change}%`,
  oneLine(summaries.adSpend),
  '',
  '🎯 *Focus this week:*',
  ...(focusBullets.length ? focusBullets : ['No anomalies this week — steady as she goes.']).map((b) => `• ${b}`),
  '',
  `📧 Full HTML report in your inbox`,
].join('\n');

return [{ json: { html, subject, slackText, weekRange: m.weekRange, generatedDate: m.generatedDate } }];
